/*
    Примечание:
    После завершения функции getname() её локальный массив temp[80] на стеке уничтожается.
    Однако память, выделенная через new в куче, продолжает жить, пока не будет вызван delete[].
    При повторном вызове функции getname() операционная система часто выделяет тот же самый
    (только что освобожденный) адрес памяти в целях оптимизации.
*/


// Стандарт С++20:

#include <format>
#include <iostream>
#include <string>                                       // Подключение заголовочного файла для применения класса std::string для работы со строками;
#include <string_view>                                  // Подключение заголовочного файла для наложения взгляда на строку без копирования данных и определения его размера;
#include <vector>                                       // Подключение заголовочного файла для применения класса vector для работы с динамическими массивами;

static std::vector<char> getname();                     // Прототип функции getname(), которая ничего не принимает и возвращает объект вектора символов. Квалификатор static ограничивает видимость функции рамками текущего файла.
                                                        // std::vector<char> — шаблонный класс-контейнер для работы с динамическим массивом символов в куче, который автоматически управляет выделением и перевыделением памяти под размер строки;
int main()
{
    std::string_view name{};                            // Объявление пустого объекта класса string_view для последующего наложения взгляда на данные без копирования памяти;
    std::vector<char>name_storage = getname();          // Вызов функции getname(), которая ничего не принимает и возвращает объект вектора символов (строки). std::vector<char> - шаблонный класс контейнер для работы с динамическим массивом символов, который автоматически управляет выделением и перевыделением памяти под размер строки;
    name = name_storage.data();                         // Объект name класса string_view накладывает взгляд на динамический массив в куче, получая адрес первого элемента name_storage через метод .data() класса-контейнера vector;
    std::cout << std::format("{} расположен по адресу {:p}\n", // Объект cout с помощью оператора << выводит отформатированную строку со строкой, на которую наложен взгляд объекта name класса string_view и адрес с помощью метода .data() класса string_view.
        name, static_cast<const void*>(name.data()));         // static_cast<const void*>(name.data()) — явно преобразует тип указателя в универсальный тип, чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};

    name_storage.clear();                               // Удаление элементов динамического массива типа char и сброс его размера в ноль без освобождения выделенной памяти в куче от элементов через метод clear() класса-контейнера vector;
    name_storage.shrink_to_fit();                       // Метод .shrink_to_fit() класса-контейнера vector принудительно возвращает неиспользованную память (в куче) обратно операционной системе;
    name = "";                                          // После удаления всех элементов и освобождения от динамического массива (в куче) объект name класса string_view все еще смотрит на ту область, где был массив. Для того чтобы взгляд больше не накладывался на тот адрес, ему присваивается пустая строка, т.е. смотрит на пустой адрес nullptr;

    name_storage = getname();                           // Повторный вызов функции getname(), которая ничего не принимает и возвращает объект вектора символов (строки). Производится повторное использование объекта name_storage класса-контейнера vector;
    name = name_storage.data();                         // Объект name класса string_view накладывает взгляд на динамический массив в куче, получая адрес первого элемента name_storage через метод .data() класса-контейнера vector;
    std::cout << std::format("{} расположен по адресу {:p}\n", // Объект cout с помощью оператора << выводит отформатированную строку со строкой, на которую наложен взгляд объекта name класса string_view и адрес с помощью метода .data() класса string_view.
        name, static_cast<const void*>(name.data()));         // static_cast<const void*>(name.data()) — явно преобразует тип указателя в универсальный тип, чтобы функция format() смогла отобразить адрес в шестнадцатеричном виде через спецификатор {:p};
}

static std::vector<char>getname()                       // Определение функции;
{
    std::string temp;                                   // Объявление пустого объекта строки класса string;
    std::cout << "Введите фамилию: ";
    std::cin >> temp;                                   // Объект cin с помощью оператора >> вводит строку с клавиатуры в объект строки;
    std::vector<char> names(temp.begin(), temp.end());  // Объект names класса-контейнера vector выделяет место в памяти (в куче) под массив строки, определяя с помощью метода .begin() класса string начало первого символа и конец последнего символа с помощью метода temp.end() класса string, тем самым класс-контейнер vector знает размер строки;
    names.push_back('\0');                            // Объекту names класса-контейнера vector в конец динамического массива в выделенной памяти (в куче) добавляется символ конца строки \0 с помощью метода .push_back() класса-контейнера vector. Это делается для корректной работы функции format(), чтобы при считывании строки функция видела нуль-терминатор и не залезла в чужую область памяти;
    return names;                                       // Функция возвращает объект вектора символов;
}


